 * - [PassActionDataOption2]: Kupon ve indirim kartı: `use`: kupon ve indirim kartının bakiyesi yoktur; yanıt kullanım sayısını verir.
 */
public sealed class PassActionData : RewloyObject() {
    /** Always present. */
    public abstract val duplicate: Boolean

    /**
     * true: bu anahtarın işlemi sonradan geri alındı (`actions/reverse` ya da `sale/reverse`). Yalnız bir tekrarda (`duplicate: true`) true olabilir: yanıt ilk isteğin sonucunu söyler, kart onu artık taşımaz. Yeni bir işlem için yeni anahtar gönderin.
     *
     * Always present.
     */
    public abstract val reversed: Boolean

    internal companion object {
        private val shapes = listOf(
            Wire.Shape(listOf("balance", "duplicate", "reversed", "card"), listOf("balance", "duplicate", "detail", "promotion", "reversed", "card"), null, null),
            Wire.Shape(listOf("status", "duplicate", "uses", "usesLeft", "reversed", "card"), listOf("status", "duplicate", "uses", "usesLeft", "reversed", "card"), null, null),
        )

        fun read(v: JsonValue, path: String): PassActionData = when (Wire.pickShape(v, path, shapes)) {
            0 -> PassActionDataOption1.read(v, path)
            else -> PassActionDataOption2.read(v, path)
        }
    }
}

